#include <iostream>
#include <cstdint>

int main() {
    union {
        int i;
        float f;
    } u;
    u.i = 1;  // Set integer value
    float* aliasPtr = reinterpret_cast<float*>(&u.i);  // Attempt to alias
    *aliasPtr = 2.0f;  // This violates strict aliasing if compiler optimizes
    std::cout << u.i << std::endl;  // May output garbage due to optimizations
    return 0;
}
